"""M4 Intelligence Center v2.

Direct replacement for the legacy observable operator. Uses the production Empty
Chair brand assets, keeps M4 narration non-blocking, and unlocks Web Audio from the
owner's click so ElevenLabs audio can play reliably on mobile Safari.
"""
from fastapi import Request
from fastapi.responses import HTMLResponse

import app as core


def _page(request: Request):
    user, redirect = core.login_required_redirect(request)
    if redirect:
        return redirect
    return HTMLResponse(_HTML, headers={"Cache-Control": "no-store, no-cache, must-revalidate, max-age=0"})


_HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Empty Chair · M4 Intelligence</title><link rel="stylesheet" href="/static/style.css?v=m4v2"><style>
:root{--m4panel:#0d0f0d;--m4soft:#090b09}body{background:#080908;color:var(--cream)}.shell{max-width:1500px;margin:auto;padding:0 28px 70px}.top{position:sticky;top:0;z-index:30;display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:96px;background:rgba(8,9,8,.97);border-bottom:1px solid var(--line);backdrop-filter:blur(14px)}.brand{display:flex;align-items:center;gap:17px}.brand img{width:190px;max-height:72px;object-fit:contain}.brand-copy b{display:block;font:400 25px var(--cartoon);text-transform:uppercase}.brand-copy span{display:block;margin-top:4px;color:var(--signal);font:800 9px var(--body);letter-spacing:.13em}.actions{display:flex;gap:8px}.hero{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:36px;align-items:center;padding:42px 0 30px}.ey{color:var(--signal);font:400 14px var(--cartoon);letter-spacing:.04em;text-transform:uppercase}.hero h1{margin:7px 0 14px;font:400 clamp(58px,7vw,100px)/.85 var(--cartoon);text-transform:uppercase}.hero p{max-width:810px;color:var(--cream-dim);font-size:14px;line-height:1.6}.presence{min-height:220px;display:grid;place-items:center;position:relative;border:1px solid var(--line);background:radial-gradient(circle,rgba(199,255,62,.12),#0d0f0d 60%);box-shadow:4px 4px 0 #000}.presence:before{content:'M4';display:grid;place-items:center;width:92px;height:92px;border:1px solid var(--signal);border-radius:50%;color:var(--signal);font:400 38px var(--cartoon);box-shadow:0 0 45px rgba(199,255,62,.23);animation:pulse 3s ease-in-out infinite}.presence.thinking:before{animation-duration:.7s}.presence.acting:before{box-shadow:0 0 70px rgba(199,255,62,.5)}.presence label{position:absolute;bottom:15px;color:var(--cream-dim);font:800 9px var(--body);letter-spacing:.11em;text-transform:uppercase}@keyframes pulse{50%{transform:scale(1.08)}}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-bottom:18px}.metric{padding:18px;border:1px solid var(--line);background:var(--m4panel);box-shadow:4px 4px 0 #000}.metric b{display:block;font:400 30px var(--display)}.metric small{display:block;margin-top:5px;color:var(--cream-dim);font:400 13px var(--cartoon);text-transform:uppercase}.metric.money b{color:var(--signal)}.main-grid{display:grid;grid-template-columns:285px minmax(0,1fr) 340px;gap:8px}.pane{min-width:0;min-height:590px;padding:20px;border:1px solid var(--line);background:var(--m4panel);box-shadow:4px 4px 0 #000}.pane h2{margin:6px 0 8px;font:400 31px var(--cartoon);text-transform:uppercase}.sub{margin-bottom:16px;color:var(--muted);font-size:12px;line-height:1.5}.opening,.person,.reason,.calendar-card{padding:12px;margin-bottom:8px;border:1px solid var(--line-soft);background:var(--m4soft)}.opening.active,.person.focus,.reason.active{border-color:var(--signal);box-shadow:inset 3px 0 0 var(--signal)}.opening b,.person>b,.calendar-card b{display:block;font-size:12px}.opening span,.person>span,.calendar-card span{display:block;margin-top:5px;color:var(--muted);font:600 9px ui-monospace,monospace}.lanes{display:grid;grid-template-columns:1fr 1fr;gap:10px}.lane{min-height:250px;padding:10px;border:1px solid var(--line);background:var(--m4soft)}.lane h3{margin:0 0 10px;color:var(--cream-dim);font:400 14px var(--cartoon);text-transform:uppercase}.confidence{display:inline-flex;gap:6px;margin-top:9px;padding:5px 8px;border:1px solid var(--line);font:900 9px ui-monospace,monospace;letter-spacing:.08em}.confidence.high{color:var(--signal);border-color:var(--signal)}.confidence.medium{color:#e4c871;border-color:#d8b65a}.confidence.low{color:#e39191;border-color:#b96565}.explain{margin-top:10px;padding-top:9px;border-top:1px solid var(--line-soft)}.explain b{font:400 13px var(--cartoon);text-transform:uppercase;color:var(--cream-dim)}.explain ul{list-style:none;padding:0;margin:6px 0}.explain li{font-size:10px;line-height:1.45;color:var(--cream-dim);margin:3px 0}.good:before{content:'+ ';color:var(--signal);font-weight:900}.risk:before{content:'− ';color:#e39191;font-weight:900}.learn{margin-top:8px;padding:8px;border-left:2px solid #d8b65a;background:#11130e;color:#c9bea0;font-size:9px}.score{color:var(--signal)!important}.reason{opacity:.42;transition:.25s}.reason.active{opacity:1}.reason.done{opacity:.8}.reason strong{display:block;font-size:11px}.reason small{display:block;margin-top:4px;color:var(--muted)}.log{min-height:150px;margin-top:12px;padding:13px;border:1px solid var(--line);background:#070907;white-space:pre-wrap;font:500 10px/1.65 ui-monospace,monospace;color:var(--cream-dim)}.voice{margin-top:10px;padding:10px 12px;border-left:2px solid var(--signal);background:#090b09;color:var(--cream-dim);font-size:10px}.voice.error{border-left-color:#e39191;color:#e39191}.calendar{margin-top:15px}.offer{position:fixed;right:22px;bottom:22px;z-index:50;display:none;width:min(390px,calc(100vw - 44px));padding:18px;border:1px solid var(--signal);background:#0d0f0d;box-shadow:0 24px 70px #000}.offer.show{display:block}.offer-state{color:var(--signal);font:400 14px var(--cartoon);text-transform:uppercase}.offer h3{font:400 27px var(--cartoon);text-transform:uppercase;margin:5px 0}.offer p{color:var(--cream-dim);font-size:12px;line-height:1.5}@media(max-width:1000px){.hero,.main-grid{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}.pane{min-height:auto}}@media(max-width:650px){.shell{padding:0 15px 50px}.top{align-items:flex-start;flex-direction:column;padding:12px 0}.brand img{width:160px}.actions{width:100%}.actions .button{flex:1}.hero h1{font-size:58px}.lanes{grid-template-columns:1fr}}
</style></head><body><main class="shell"><header class="top"><div class="brand"><img src="/static/D8F5F51D-90EE-45DE-9D95-DB078BDEB87E.png?v=4" alt="Empty Chair"><div class="brand-copy"><b>M4 Intelligence</b><span>RANK · EXPLAIN · ACT · LEARN</span></div></div><div class="actions"><button id="run" class="button">Run M4</button><a href="/m4" class="button secondary">M4 Home</a></div></header><section class="hero"><div><div class="ey">EMPTY CHAIR // DECISION INTELLIGENCE</div><h1>KNOW WHO TO CALL FIRST.</h1><p>M4 reads the opening, ranks the available demand, explains the strongest choice, exposes uncertainty, and tells Concierge which missing answer would improve the decision most.</p></div><div id="presence" class="presence"><label id="state">observing shop state</label></div></section><section class="metrics"><div class="metric"><b id="customers">—</b><small>Customers observed</small></div><div class="metric"><b id="gaps">—</b><small>Open gaps</small></div><div class="metric"><b id="ev">—</b><small>Top expected value</small></div><div class="metric"><b id="qscore">—</b><small>M4 queue score</small></div><div class="metric money"><b id="revenue">$0</b><small>Recovered revenue</small></div></section><section class="main-grid"><div class="pane"><div class="ey">01 // INVENTORY</div><h2>Open chair time</h2><div class="sub">Start with expiring capacity — not a customer blast.</div><div id="openings">Loading…</div><div class="calendar"><div class="ey">Recovered calendar</div><div id="calendar"></div></div></div><div class="pane"><div class="ey">02 // RANKING</div><h2>Population → shortlist</h2><div class="lanes"><div class="lane"><h3>Candidate pool</h3><div id="pool"></div></div><div class="lane"><h3>M4 shortlist</h3><div id="short"></div></div></div><div id="log" class="log">M4 // ready</div><div id="voice" class="voice">M4 VOICE // ready</div></div><div class="pane"><div class="ey">03 // REASONING</div><h2>What M4 is doing</h2><div id="reasoning"><div class="reason"><strong>1. Read the opening</strong><small>Value, artist, style, date and time.</small></div><div class="reason"><strong>2. Filter eligibility</strong><small>Consent and contact safety.</small></div><div class="reason"><strong>3. Measure fit</strong><small>Artist, style, budget, distance and timing.</small></div><div class="reason"><strong>4. Rank incremental value</strong><small>Who is most worth contacting now?</small></div><div class="reason"><strong>5. Measure confidence</strong><small>Is the evidence strong enough?</small></div><div class="reason"><strong>6. Explain the choice</strong><small>Show the owner why this person is first.</small></div><div class="reason"><strong>7. Learn or act</strong><small>Ask for missing evidence or recommend action.</small></div></div></div></section></main><aside id="offer" class="offer"><div class="offer-state">M4 RECOMMENDATION</div><h3 id="offerName"></h3><p id="offerText"></p></aside><script>
(()=>{const $=id=>document.getElementById(id),run=$('run'),presence=$('presence'),stateEl=$('state'),voice=$('voice'),log=$('log'),openings=$('openings'),pool=$('pool'),short=$('short'),offer=$('offer');let data=null,audioCtx=null;const sleep=ms=>new Promise(r=>setTimeout(r,ms));function uiState(text,mode='thinking'){presence.className='presence '+mode;stateEl.textContent=text;log.textContent+='\n'+text}function step(n){document.querySelectorAll('.reason').forEach((x,i)=>{x.classList.toggle('active',i===n);x.classList.toggle('done',i<n)})}function unlockAudio(){try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const b=audioCtx.createBuffer(1,1,22050),s=audioCtx.createBufferSource();s.buffer=b;s.connect(audioCtx.destination);s.start(0)}catch(e){}}async function play64(b64){if(!b64)return;audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();await audioCtx.resume();const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));const buf=await audioCtx.decodeAudioData(bytes.buffer.slice(0));const src=audioCtx.createBufferSource();src.buffer=buf;src.connect(audioCtx.destination);src.start(0);return new Promise(r=>{src.onended=r;setTimeout(r,18000)})}function narrate(key){(async()=>{try{const f=new FormData();f.append('key',key);const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),12000);const r=await fetch('/api/m4/operator/narrate',{method:'POST',body:f,cache:'no-store',signal:ctl.signal});clearTimeout(timer);const j=await r.json();if(j.text)log.textContent+='\nM4: '+j.text;if(!j.audio_base64)throw Error(j.voice_error||j.error||'ElevenLabs returned no audio');voice.classList.remove('error');voice.textContent='M4 VOICE // speaking';await play64(j.audio_base64);voice.textContent='M4 VOICE // ready'}catch(e){voice.classList.add('error');voice.textContent='M4 VOICE ERROR // '+(e&&e.message?e.message:String(e))}})()}async function load(reset=true){const r=await fetch('/api/m4/operator/status',{cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.error||'Could not load M4');if((!j.openings||!j.openings.length)&&j.synthetic&&reset){const rr=await fetch('/api/m4/operator/reset-synthetic',{method:'POST'});if(rr.ok)return load(false)}data=j;$('customers').textContent=j.dataset?.customers||0;$('gaps').textContent=(j.openings||[]).length;openings.innerHTML='';(j.openings||[]).forEach(o=>{const d=document.createElement('div');d.className='opening';d.dataset.id=o.id;d.innerHTML=`<b>${o.style||'Open chair'} · $${Number(o.price||0).toLocaleString()}</b><span>${o.date} ${o.start_time}–${o.end_time||''} · ${o.artist_id}</span>`;openings.appendChild(d)});run.disabled=!(j.openings||[]).length}async function preview(o){const f=new FormData();f.append('opening_id',o.id);const r=await fetch('/api/m4/operator/preview',{method:'POST',body:f,cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.error||'Preview failed');return j}function card(c,focus=false){const d=document.createElement('div');d.className='person'+(focus?' focus':'');const label=(c.m4_confidence_label||'LOW').toLowerCase(),why=(c.why_this_person||[]).slice(0,4).map(x=>`<li class="good">${x}</li>`).join(''),risk=(c.risk_factors||[]).slice(0,2).map(x=>`<li class="risk">${x}</li>`).join(''),missing=(c.missing_high_value_signals||[]).slice(0,3);d.innerHTML=`<b>${c.name||c.customer_id}</b><span>booking ${Math.round(Number(c.booking_probability||0)*100)}% · uplift ${Math.round(Number(c.incremental_uplift||0)*100)}%</span><span class="score">queue ${c.queue_score} · EV $${Number(c.expected_value||0).toFixed(0)}</span><div class="confidence ${label}">${c.m4_confidence_label||'LOW'} ${Number(c.m4_confidence_score||0)}% → ${c.recommended_action==='ACT'?'ACT':c.recommended_action==='RECOMMEND'?'RECOMMEND':'LEARN FIRST'}</div><div class="explain"><b>Why M4 ranks this person</b><ul>${why||'<li>Limited supporting evidence</li>'}${risk}</ul>${missing.length?`<div class="learn"><b>M4 WANTS TO LEARN:</b> ${missing.join(' · ')}</div>`:''}</div>`;return d}run.onclick=async()=>{unlockAudio();run.disabled=true;run.textContent='M4 RUNNING…';offer.classList.remove('show');pool.innerHTML='';short.innerHTML='';log.textContent='M4 // intelligence run started';document.querySelectorAll('.reason').forEach(x=>x.classList.remove('active','done'));try{if(!data)await load();step(0);uiState('Reading open chair inventory');narrate('scan');await sleep(450);const selected=[...(data.openings||[])].sort((a,b)=>Number(b.price||0)-Number(a.price||0))[0];if(!selected)throw Error('No open chair available');document.querySelectorAll('.opening').forEach(x=>x.classList.toggle('active',x.dataset.id===selected.id));step(1);uiState('Filtering eligible demand');narrate('filter');await sleep(450);step(2);uiState('Comparing artist, style and practical fit');narrate('fit');const p=await preview(selected);const ranked=p.m4_top_candidates||[];if(!ranked.length)throw Error('No eligible customer candidates');pool.innerHTML='';ranked.slice(0,6).forEach(c=>pool.appendChild(card(c,false)));await sleep(500);step(3);uiState('Ranking incremental value');await sleep(400);short.innerHTML='';ranked.slice(0,3).forEach((c,i)=>short.appendChild(card(c,i===0)));const top=ranked[0];$('ev').textContent='$'+Number(top.expected_value||0).toFixed(0);$('qscore').textContent=top.queue_score;step(4);uiState('Measuring confidence');await sleep(400);step(5);uiState('Explaining the strongest match');narrate('choose');log.textContent+=`\n\nOWNER VIEW // ${top.m4_confidence_label||'LOW'} ${Number(top.m4_confidence_score||0)}% → ${top.recommended_action||'LEARN_OR_FALLBACK'}`;if((top.why_this_person||[]).length)log.textContent+='\nWHY: '+top.why_this_person.slice(0,4).join(' • ');if((top.risk_factors||[]).length)log.textContent+='\nRISK: '+top.risk_factors.slice(0,2).join(' • ');await sleep(450);step(6);uiState(top.recommended_action==='ACT'?'Recommendation ready to act':'More evidence recommended before automatic action','acting');$('offerName').textContent=top.name||top.customer_id;$('offerText').textContent=`${top.m4_confidence_label||'LOW'} confidence · ${Number(top.m4_confidence_score||0)}%. ${top.recommended_action==='ACT'?'M4 recommends this customer first.':'M4 recommends learning more before automatic outreach.'}`;offer.classList.add('show');narrate('sent');run.textContent='Run M4 again';run.disabled=false}catch(e){uiState('Run stopped: '+(e&&e.message?e.message:String(e)),'');voice.textContent='M4 VOICE // run error';run.textContent='Retry M4';run.disabled=false}};load().catch(e=>{log.textContent='M4 load error: '+e.message;run.disabled=false;run.textContent='Retry M4'})})();
</script></body></html>'''


for route in core.app.routes:
    if getattr(route, "path", None) == "/m4-operator-live" and getattr(route, "methods", None) and "GET" in route.methods:
        route.endpoint = _page
        break
